    steps = [
        f"讀題定位：圈出「{tag}」及題目中的餘額、帳單、額度、付款時點、退款或責任資料。",
        f"追蹤資金流程：判斷付款前是否已有餘額、付款後是否形成帳款，再對照使用限制；本題核心是「{explanation}」",
        f"核對正解：選項 {answer_id}「{answer}」與題幹給出的支付制度和證據相符。",
        "排除誘答：找出只看卡片外觀、把能付款等同信用、忽略預付餘額或把交易紀錄誤當成完整制度證據的說法。",
        "結論回查：確認答案同時區分支付工具、貨幣功能、契約責任與資料不足，不超出題幹可支持的範圍。",
    ]
    return {"id": f"question-social-content-civ-bp-iv-3-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": option_objects, "knowledgeIds": ["kg-social-content-civ-bp-iv-3"], "difficulty": "medium", "answer": {"value": answer_id, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "公立學校公開社會課程與試題入口；本題只研究公開試題與課程評量的能力結構。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫信用卡與儲值卡的付款時點、資金來源、額度、餘額、紀錄、遺失、退款、情境選擇與資料界線；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-civ-bp-iv-3", "examPatternRefs": refs, "solutionStrategy": "先追蹤資金來源與付款時點，再檢查餘額、帳單、額度、退款、掛失與責任規則，最後依使用情境和證據完整性作有條件判斷。", "solutionSteps": steps}

